def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_ints = sorted((tuple(i) for i in intervals), key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = sorted_ints[0]
    for start, end in sorted_ints[1:]:
        if start <= cur_end:            # overlapping or touching
            if end > cur_end:
                cur_end = end
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

import heapq
from typing import List, Tuple, Dict, Set

def toposort(nodes: List[str], edges: List[Tuple[str, str]]) -> List[str]:
    # Build in-degree map and adjacency list, ignoring duplicate edges
    in_degree: Dict[str, int] = {node: 0 for node in nodes}
    adjacency: Dict[str, Set[str]] = {node: set() for node in nodes}
    seen_edges: Set[Tuple[str, str]] = set()

    for src, dst in edges:
        if src == dst:
            raise ValueError("Self-loop detected")
        edge = (src, dst)
        if edge in seen_edges:
            continue  # ignore duplicate
        seen_edges.add(edge)
        adjacency[src].add(dst)
        in_degree[dst] += 1

    # Initialize min-heap with nodes having zero in-degree
    zero_nodes: List[str] = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(zero_nodes)

    result: List[str] = []
    while zero_nodes:
        node = heapq.heappop(zero_nodes)
        result.append(node)
        for neighbor in adjacency[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(zero_nodes, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if not isinstance(limit, int) or limit <= 0:
        raise ValueError
    result = []
    current = []
    current_sum = 0
    for name, weight in items:
        if not isinstance(weight, int) or weight <= 0 or weight > limit:
            raise ValueError
        if current_sum + weight > limit:
            if current:
                result.append(current)
            current = [name]
            current_sum = weight
        else:
            current.append(name)
            current_sum += weight
    if current:
        result.append(current)
    return result

import re

def parse_env(text: str) -> dict:
    """Parse environment assignments from *text*.

    Returns a dict mapping keys to values.
    """
    env = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue

        eq_pos = line.find('=')
        if eq_pos == -1:
            raise ValueError(f"Invalid line (missing '='): {raw_line!r}")

        key = line[:eq_pos].strip()
        value = line[eq_pos + 1 :].strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] in ("'", '"'):
            value = value[1:-1]

        env[key] = value

    return env
